<script setup lang="ts">
import {ref} from 'vue'
import {request} from '../api'
import {newId} from '../ids'
const props=defineProps<{content:any;sourceMedia?:{key:string;path:string}[];plannedPlaces?:any[];disabled?:boolean}>()
const emit=defineEmits<{(e:'change'):void}>()
const places=ref<Record<string,any[]>>(Object.create(null)),media=ref<Record<string,any[]>>(Object.create(null)),queries=ref<Record<string,string>>(Object.create(null)),busy=ref(''),error=ref('')
function addPlace(){if(props.disabled||props.content.places.length>=100)return;props.content.places.push({key:'place_'+newId(),kind:'l',name:'',existing_id:null,city:'',address:''});emit('change')}
function removePlace(place:any){
 if(props.disabled)return
 const used=props.content.records.some((r:any)=>(r.foods||[]).some((f:any)=>f.place_key===place.key)||(r.photos||[]).some((p:any)=>p.place_key===place.key)||(r.travel?.activities||[]).some((a:any)=>a.place_key===place.key)||(r.body||'').includes('{{place:'+place.key+'}}')||!!place.existing_id&&(r.body||'').includes(place.existing_id)||!!place.name&&(r.body||'').includes(place.name))
 if(used){error.value='此地点仍被候选正文、餐饮、照片或活动引用，请先明确解除；不会自动改写正文或地点库。';return}
 props.content.places=props.content.places.filter((p:any)=>p!==place);emit('change')
}
const kinds=[['l','地点 / 地区'],['f','餐厅 / 美食地点'],['s','景点'],['h','住宿'],['t','交通'],['c','咖啡 / 饮品'],['p','购物']]
async function search(kind:'media'|'places',item:any){busy.value=kind+item.key;error.value='';try{const result=await request('/admin/archive/'+kind+'?'+new URLSearchParams({q:queries.value[item.key]|| (kind==='places'?item.name:''),page:'1',page_size:'20'}));(kind==='places'?places:media).value[item.key]=result.items}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=''}}
function choosePlace(item:any,event:Event){const id=(event.target as HTMLSelectElement).value;item.existing_id=id||null;if(id){const selected=places.value[item.key]?.find(p=>p.id===id);if(selected){item.name=selected.name;item.city=selected.city;item.address=selected.address}}emit('change')}
function chooseMedia(item:any,event:Event){const id=(event.target as HTMLSelectElement).value;item.existing_id=id||null;item.path=id?null:props.sourceMedia?.find(m=>m.key===item.key)?.path||null;emit('change')}
</script>
<template><section class="resource-mapping" @input="emit('change')" @change="emit('change')"><p v-if="error" class="error" role="alert">{{error}}</p><button type="button" class="quiet" :disabled="disabled||content.places.length>=100" @click="addPlace">补充地点候选（确认前不创建）</button><details v-if="content.places.length" open><summary>地点身份与城市映射</summary><p>同名分店请明确选择；不根据名称猜测坐标。选择目录身份只用于本次关联，不修改地点库。</p><article v-for="place in content.places" :key="place.key" class="resource-map-item"><h4>{{place.key}} · {{place.name}}</h4><button type="button" class="quiet" :disabled="disabled" @click="removePlace(place)">仅移除此地点候选（地点库不变）</button><p v-if="plannedPlaces?.find(p=>p.key===place.key)" class="muted">最近校验计划：{{plannedPlaces.find(p=>p.key===place.key).action==='reuse'?'复用现有地点':'确认后新建地点'}} · {{plannedPlaces.find(p=>p.key===place.key).city||plannedPlaces.find(p=>p.key===place.key).region||'待分类'}} · {{plannedPlaces.find(p=>p.key===place.key).address}}</p><div class="resource-map-fields"><label>标记类型<select v-model="place.kind" :disabled="disabled"><option v-for="[key,name] in kinds" :key="key" :value="key">{{name}}</option></select></label><label>地点名称<input v-model="place.name" maxlength="200" :disabled="disabled||!!place.existing_id"></label><label>明确的城市<input v-model="place.city" maxlength="100" :disabled="disabled||!!place.existing_id"></label><label>地址<input v-model="place.address" maxlength="500" :disabled="disabled||!!place.existing_id"></label></div><div class="actions"><label>查找已有地点<input v-model="queries[place.key]" :placeholder="place.name" maxlength="100" :disabled="disabled" @keydown.enter.prevent="search('places',place)"></label><button type="button" class="quiet" :disabled="disabled||!!busy" @click="search('places',place)">查找已有地点身份</button></div><label>采用地点库身份<select :value="place.existing_id||''" :disabled="disabled" @change="choosePlace(place,$event)"><option value="">未指定身份，按明确名称、城市与类型匹配或新建</option><option v-if="place.existing_id&&!places[place.key]?.some(p=>p.id===place.existing_id)" :value="place.existing_id">已指定 {{place.name}}（保存前由服务器核对）</option><option v-for="found in places[place.key]||[]" :key="found.id" :value="found.id" :disabled="!found.active">{{found.name}} · {{found.city||found.region||'待分类'}} · {{found.category}}</option></select></label></article></details>
<details v-if="content.media.length" open><summary>照片来源、说明与展示方式</summary><p>包内路径是 ZIP 相对路径，不是服务器存储位置。映射现有媒体不复制原图，也不修改图库标题与说明。</p><article v-for="photo in content.media" :key="photo.key" class="resource-map-item"><h4>{{photo.key}} · {{photo.path||'复用媒体库照片'}}</h4><div class="resource-map-fields"><label>替代文字<input v-model="photo.alt" maxlength="1000" :disabled="disabled"></label><label>记录级照片说明<input v-model="photo.caption" maxlength="2000" :disabled="disabled"></label><label>显示宽度<select v-model="photo.widthPercent" :disabled="disabled"><option :value="null">按像素宽度</option><option v-for="width in [30,60,100]" :key="width" :value="width">{{width}}%</option></select></label><label>像素宽度<input v-model.number="photo.width" type="number" min="120" max="1600" :disabled="disabled"></label><label>对齐<select v-model="photo.align" :disabled="disabled"><option value="left">左</option><option value="center">居中</option><option value="right">右</option></select></label><label>布局<select v-model="photo.layout" :disabled="disabled"><option value="auto">自动</option><option value="single">独立大图</option><option value="grid">照片网格</option></select></label></div><div class="actions"><label>搜索已有图片<input v-model="queries[photo.key]" maxlength="100" :disabled="disabled" @keydown.enter.prevent="search('media',photo)"></label><button type="button" class="quiet" :disabled="disabled||!!busy" @click="search('media',photo)">查找可复用图片</button></div><label>采用图片来源<select :value="photo.existing_id||''" :disabled="disabled" @change="chooseMedia(photo,$event)"><option value="">{{sourceMedia?.some(m=>m.key===photo.key)?'使用本次 ZIP 内的原图':'请明确选择已有图片'}}</option><option v-if="photo.existing_id&&!media[photo.key]?.some(m=>m.id===photo.existing_id)" :value="photo.existing_id">已指定现有图片（服务器会重新核对）</option><option v-for="found in media[photo.key]||[]" :key="found.id" :value="found.id">{{found.title||found.filename}} · {{found.width}}×{{found.height}}</option></select></label></article></details></section></template>
<style scoped>.resource-mapping{min-width:0}.resource-mapping details{margin-block:16px;border-top:1px solid var(--ui-line);padding-top:12px}.resource-map-item{padding-block:16px;border-top:1px solid var(--ui-line)}.resource-map-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:12px}.resource-mapping label{display:block}.resource-mapping h4{overflow-wrap:anywhere}.resource-mapping .actions{flex-wrap:wrap}</style>
